def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None, db=None, imp_user=None, dehydration_hooks=None, hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """

    # Process parameters
    if mode in (None, "READ"):
        action = "BEGIN_RELATIONSHIP_READ"
    elif mode == "WRITE":
        action = "BEGIN_RELATIONSHIP_WRITE"
    else:
        raise ValueError("Invalid transaction mode: {!r}".format(mode))
    if bookmarks is not None and not isinstance(bookmarks, list):
        raise ValueError("Bookmarks must be a list of bookmark URIs, not {!r}".format(bookmarks))
    if metadata is not None and not isinstance(metadata, dict):
        raise ValueError("Metadata must be a dict, not {!r}".format(metadata))
    if timeout is not None and timeout < 0:
        raise ValueError("Timeout must be a positive number, not {!r}".format(timeout))
    if db is not None and not isinstance(db, str):
        raise ValueError("Database name must be a string, not {!r}".format(db))
    if imp_user is not None and not isinstance(imp_user, str):
        raise ValueError("Impersonated user must be a string, not {!r}".format(imp_user))
    if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
        raise ValueError("Dehydration hooks must be a dictionary, not {!r}".format(dehydration_hooks))
    if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
        raise ValueError("Hydration hooks must be a dictionary, not {!r}".format(hydration_hooks))

    # Build and send the BEGIN message
    message = {
        "action": "begin",
        "parameters": {
            "mode": mode
        }
    }
    if bookmarks is not None:
        message["parameters"]["bookmarks"] = bookmarks
    if metadata is not None:
        message["parameters"]["metadata"] = metadata
    if timeout is not None:
        message["parameters"]["timeout"] = timeout
    if db is not None:
        message["parameters"]["database"] = db
    if imp_user is not None:
        message["parameters"]["imp_user"] = imp_user
    if dehydration_hooks is not None:
        message["parameters"]["dehydration_hooks"] = dehydration_hooks
    if hydration_hooks is not None:
        message["parameters"]["hydration_hooks"] = hydration_hooks
    self.write_message(message)

    # Wait for response
    response = self.read_until_message_type("RESPONSE")

