        if graph.points is not None:
            points = graph.points
        else:
            points = graph.copy

        if points.ndim == 1:
            if self.separator == "":
                csv = "\n".join([",".join(map(str, row)) for row in points])
            else:
                csv = "\n".join([self.separator.join(map(str, row)) for row in points])
            if self.header is not None:
                csv = self.header + "\n" + csv
            return csv

        elif points.ndim == 2:
            headers = ["x{}".format(i) for i in range(points.shape[1])]
            headers += ["y{}".format(i) for i in range(points.shape[1])]
            csv = ""
            for row in points:
                csv += self.separator.join([str(cell) for cell in row]) + "\n"

