def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Generates part of a default ``observer_schema`` recursively from part of a Kubernetes resource.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    """

    observer_schema = {}
    for key, value in manifest_dict.items():
        if isinstance(value, dict):
            observer_schema[key] = generate_default_observer_schema_dict(value)
        elif isinstance(value, list):
            observer_schema[key] = []
            for item in value:
                if isinstance(item, dict):
                    observer_schema[key].append(generate_default_observer_schema_dict(item))
                else:
                    observer_schema[key].append(None)
        else:
            observer_schema[key] = None

    if first_level:
        id_keys = ["name", "namespace", "kind", "uid"]
        for key in id_keys:
            if key in manifest_dict:
                observer_schema[key] = manifest_dict[key]

    return observer_schema

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    new_dict = {}

    for key, value in manifest_dict.items():
        if isinstance(value, list):
            new_dict[key] = [generate_default_observer_schema_dict(element, first_level=first_level) for element in value]
        elif isinstance(value, dict):
            new_dict[key] = generate_default_observer_schema_dict(value, first_level=first_level)
        else:
            new_dict[key] = None

    if first_level:
        identifier_fields = {"kind", "apiVersion"}
        for field in identifier_fields:
            if field in new_dict:
                new_dict[field] = manifest_dict[field]

    return new_dict

