            continue

        if subinfo.get("metadata", {}).get("is_map"):
            if subfield_name in response:
                for key, value in response[subfield_name].items():
                    if key not in last_applied_manifest[subfield]:
                        last_applied_manifest[subfield][key] = {}
                    update_last_applied_manifest_dict_from_resp(last_applied_manifest[subfield][key], subinfo, value)
            else:
                raise KeyError(f"Field '{subfield_name}' is not present in the Kubernetes response.")
        elif subinfo.get("metadata", {}).get("is_list"):
            if subfield_name in response:
                last_applied_manifest[subfield] = last_applied_manifest.get(subfield, [])
                for item in response[subfield_name]:
                    if item not in last_applied_manifest[subfield]:
                        update_last_applied_manifest_dict_from_resp(last_applied_manifest[subfield][-1], subinfo, item)
            else:
                raise KeyError(f"Field '{subfield_name}' is not present in the Kubernetes response.")

    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this function is called recursively to update a partial ``last_applied_manifest`` from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in ``last_applied_manifest`` if they are not yet present

    last_applied_manifest = last_applied_manifest or {}

    for field_name, field_schema in observer_schema.items():
        if field_name not in response:
            raise KeyError(f"Observed field {field_name} is not present in Kubernetes response")
        last_applied_manifest[field_name] = response[field_name]

        if field_schema["type"] == "object":
            last_applied_manifest[field_name] = update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[field_name], field_schema["properties"], response[field_name]
            )
        elif field_schema["type"] == "array":
            last_applied_manifest[field_name] = [
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[field_name][0], field_schema["items"], response[field_name][0]
                )
            ]

def update_last_applied_manifest_dict_from_resp(last_applied_manifest, observer_schema, response):
    for field_name, field_schema in observer_schema.items():
        if field_name not in response:
            raise KeyError("Observed field is not present in the Kubernetes response")

        if field_schema["type"] == "dict":
            if field_name not in last_applied_manifest or last_applied_manifest[field_name] is None:
                last_applied_manifest[field_name] = {}
            update_last_applied_manifest_dict_from_resp(last_applied_manifest[field_name], field_schema["properties"], response[field_name])
        elif field_schema["type"] == "list":
            if field_name not in last_applied_manifest or last_applied_manifest[field_name] is None:
                last_applied_manifest[field_name] = []
            for item in response[field_name]:
                if item not in last_applied_manifest[field_name]:
                    last_applied_manifest[field_name].append(item)
        else:
            if field_name not in last_applied_manifest or (field_name in last_applied_manifest and last_applied_manifest[field_name] is None):
                last_applied_manifest[field_name] = response[field_name]

