        if set(self.labeling_schema_versions[schema_version].keys()) != set(prior_labels.keys()):
            raise InconsistentInventoryError(f"Product label set mismatch for schema version {schema_version}: current inventory has {self.labeling_schema_versions[schema_version].keys()}, prior inventory has {prior.labeling_schema_versions[schema_version].keys()}")

    # check that for each labeling schema version, the prior inventory has the same set of label attributes and values
    for schema_version in self.labeling_schema_versions:
        for product_id in self.labeling_schema_versions[schema_version]:
            prior_labels = prior.labeling_schema_versions[schema_version][product_id]
            if set(self.labeling_schema_versions[schema_version][product_id].keys()) != set(prior_labels.keys() or set(prior_labels.values()):
