def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """

    # Check that prior is a prior version of the current inventory
    if not isinstance(prior, InventoryValidator):
        raise TypeError("prior must be an InventoryValidator object")
    elif self.id != prior.id:
        raise ValueError("prior must be a prior version of the current inventory")

    # Check that prior and self have the same attributes and values
    for attr in self.ATTRIBUTES:
        if getattr(self, attr) != getattr(prior, attr):
            raise ValueError("prior has a different value for attribute " + attr)

    # Check that prior and self have the same nested inventory elements
    # (e.g. values, etc.)
    if self.has_values() and prior.has_values():
        if set(self.values.keys()) != set(prior.values.keys()):
            raise ValueError("prior has different values than current invenotry")
        for key in self.values.keys():
            if self.values[key] != prior.values[key]:
                raise ValueError("prior has different value for key " + key)

    if self.has_entities() and prior.has_entities():
        if set(self.entities.keys()) != set(prior.entities.keys()):
            raise ValueError("prior has different values than current invenotry")
        for key in self.entities.keys():
            if self.entities[key] != prior.entities[key]:
                raise ValueError("prior has different value for key " + key)

    # Check that prior and self have the same nested validation results
    if self.has_validation_results() and prior.has_validation_results():
        if set(self.validation_results.keys()) != set(prior.validation_results.keys()):
            raise ValueError("prior has different validation results than current invenotry")
        for key in self.validation_results.keys():
            if self.validation_results[key] != prior.validation_results[key]:
                raise ValueError("prior has different validation result for key " + key)

    # Check that prior and self are not case 2
    if self.is_case_2 and prior.is_case_2:
        raise ValueError("prior cannot be a case 2 inventory")

    # Check that prior and self have the same attribute-mapping
    if self.ATTRIBUTE_MAPPING != prior.ATTRIBUTE_MAPPING:
        raise ValueError("prior has different attribute mapping than current inventory")

    # Check that prior and self have the same validation-mapping
    if self.VALIDATION_MAPPING != prior.VALIDATION_MAPPING:
        raise ValueError("prior has different validation mapping than current inventory")

    # Check that prior and self have the same valid-values-mapping
    if self.VALID_VALUES_MAPPING != prior.VALID_VALUES_MAPPING:
