    if not isinstance(fixity["origin"], str) or not fixity["origin"]:
        raise ValueError("Fixity origin is not a non-empty string")

    # Check if the manifest files are listed in the fixity block
    for file in manifest_files:
        if file not in fixity.get("files", []):
            raise ValueError(f"File {file} is not listed in the fixity block")

    # Check if the fixity block is otherwise consistent
    if not all(isinstance(value, (str, list)) for value in fixity.values()):
