    """Return a pretty formatted representation of self."""
    if debug:
        print(f"Pretty printing Element at depth {indent}")
    rv = f"{self.__class__.__name__}['{self.id}'"
    if self.attributes:
        rv += ":"
        for key, val in self.attributes.items():
            rv += f"\n{indent*'  '}{key}='{val}'"
    for child in self.children:
        rv += f"\n{indent*'  '}{child.pretty(indent + 1)}"
    rv += "\n" + "'"*indent  # closing quotes on last line
    return rv

