def absorb(self, args):
    # Check if any expression in `args` is already False or True
    for arg in args:
        if is_literal(arg):
            if arg == False:
                return []
            else:
                return args

    # Split `args` into positive and negative literals
    positive, negative = [], []
    for arg in args:
        if is_literal(arg):
            if arg[0] == "!":
                negative.append(arg[1:])
            else:
                positive.append(arg)

    # Apply absorption and negative absorption laws
    new_args = []
    for i in range(len(positive)):
        for j in range(len(negative)):
            if positive[i] in negative[j]:
                # Absorption law
                new_args.append(positive[i])
            elif negative[j] in positive[i]:
                # Negative absorption law
                new_args.append(negative[j])

    # Apply De Morgan's laws
    new_args = [expr for expr in new_args if expr != "True"]
    for i in range(len(new_args)):
        for j in range(i+1, len(new_args)):
            if is_negated(new_args[i]) and new_args[i][1] == new_args[j]:
                new_args.remove(new_args[i])

    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for i, arg in enumerate(args):
        if i > 0 and args[i - 1] & arg:
            result.append(arg)
        elif i > 0 and args[i - 1] | arg:
            result.append(args[i - 1])
        elif arg & ~args[i - 1]:
            result.append(arg & args[i - 1])
        elif arg | ~args[i - 1]:
            result.append(arg | args[i - 1])
        else:
            result.append(arg)
    return result

def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption:

    A & (A | B) = A, A | (A & B) = A

    Negative absorption:

    A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for i, arg in enumerate(args):
        if isinstance(arg, (And, Or)):
            if isinstance(arg, And):
                arg1 = arg[0]
                arg2 = arg[1]
            else:  # arg is Or
                arg1 = arg[1]
                arg2 = arg[0]
            if (arg1 == arg or arg2 == arg):
                new_args.append(arg)
            elif (arg1 == self or arg2 == self):
                new_args.extend([arg1, arg2])
            elif (arg1 == self and arg2 == self):
                new_args.append(self)
            else:
                new_args.extend([arg1, arg2])
        else:
            new_args.append(arg)
    return new_args

