def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """
    Call the given command(s).

    Args:
        commands (str or list[str]): Command(s) to run
        args (list): Arguments to pass to the command(s)
        cwd (str, optional): Current working directory
        verbose (bool, optional): Print output to console
        hide_stderr (bool, optional): Hide the error output
        env (dict, optional): Environment variables to pass to the command(s)

    Returns:
        tuple: (returncode, stdout, stderr)
    """

    if isinstance(commands, str):
        commands = [commands]
    elif not isinstance(commands, list):
        raise TypeError("commands must be a string or a list")

    if not args:
        args = []
    elif not isinstance(args, list):
        raise TypeError("args must be a list")

    if not cwd:
        cwd = os.getcwd()
    else:
        cwd = os.path.abspath(cwd)

    if verbose:
        print(f"Running command(s) in {cwd}:")
        print(f"    {commands} {args}")

    output = []
    error = []
    returncode = 0

    for command in commands:
        process = subprocess.Popen(command.split(), cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if not process.stdout or not process.stderr:
            continue

        for stream, buffer in ((process.stdout, output), (process.stderr, error)):
            for line in iter(stream.readline, b''):
                line = line.decode("utf-8")
                if verbose:
                    print(line, end="")

        returncode = process.wait()
        if returncode and not hide_stderr:
            break

    if hide_stderr:
        error = []

    if verbose:
        print()

    return returncode, "".join(output), "".join(error)

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s).

    Arguments:
        commands (list[str]): A list of commands to be executed. Each command can be a shell command or a Python callable.
        args (list[str]): A list of argument to be passed to each command. This can be either a list of strings or a list of lists of strings.
        cwd (str, optional): The current working directory to run the command from. Defaults to None.
        verbose (bool, optional): Print the executed command and its output to the console. Defaults to False.
        hide_stderr (bool, optional): Hide the stderr output. Defaults to False.
        env (dict, optional): Environment variables to be set for the command. Defaults to None.
    """

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    if not isinstance(cwd, str) and cwd is not None:
        raise ValueError("'cwd' must be a string or None")

    if not isinstance(verbose, bool):
        raise ValueError("'verbose' must be a boolean value")

    if not isinstance(hide_stderr, bool):
        raise ValueError("'hide_stderr' must be a boolean value")

    if env is not None and not isinstance(env, dict):
        raise ValueError("'env' must be a dictionary or None")

    if len(commands) != len(args):
        raise ValueError("The number of commands and arguments must match")

    for command in commands:
        if isinstance(command, str):
            command = shlex.split(command)

        if not isinstance(command, list):
            raise ValueError("'command' must be a string, a list of strings, or a callable")

        if isinstance(args, list):
            if len(command) > 1:
                raise ValueError("'args' must be a list of strings or a list of lists of strings")
            args = args[0]

        if not isinstance(args, list):
            raise ValueError("'args' must be a list of strings or a list of lists of strings")

        for arg in args:
            if not isinstance(arg, str):
                raise ValueError("'args' must be a list of strings or a list of lists of strings")

        if not callable(command) and not shutil.which(command[0]):
            raise ValueError(f"'command' must be a callable or a string that can be executed")

    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    if env is not None:
        for key, value in env.items():
            if not isinstance(value, str):
                raise ValueError(f"'env' must be a string or None")

        env = dict(os.environ, **env)

    if cwd is None:
        cwd = os.getcwd()

    if callable(command):
        if verbose:
            print(command, args)

        return command(*args)
    else:
        return subprocess.run(command, cwd=cwd, stderr=stderr, env=env).check_returncode()

def get_config():
    """
    Create, populate and return the VersioneerConfig() object.
    """
    import re
    from distutils.version import LooseVersion
    from xml.etree import ElementTree

    # Parse the configuration file
    try:
        tree = ElementTree.parse("versioneer.xml")
        root = tree.getroot()
    except Exception as e:
        raise Exception("Unable to parse 'versioneer.xml': " + str(e))

    # Create a new VersioneerConfig object
    config = VersioneerConfig()

    # Populate the object with data from the configuration file
    for child in root:
        if child.tag == "pattern":
            pattern = child.text
            if pattern is not None:
                config.pattern = pattern
        elif child.tag == "maximum_match":
            maximum_match = child.text
            if maximum_match is not None:
                config.maximum_match = maximum_match
        elif child.tag == "minimum_match":
            minimum_match = child.text
            if minimum_match is not None:
                config.minimum_match = minimum_match

    return config

