def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        root_inventory = self.root_inventory()
        version_inventories = {}
        version_digests = {}

        # Some versions may have a stream specified – in this case, a separate inventory
        # is generated for streams, which avoids re-scanning the same content.
        stream_inventories = {}

        for version_dir in version_dirs:
            version = self.versions[version_dir]
            inventory = version.inventory()
            if inventory is None:
                # Don't store any inventory for versions that lack it
                continue
            if version.stream is not None:
                stream_inventories[version] = inventory
            else:
                version_inventories[version] = inventory

            version_digest = manifest_digest(inventory)
            if version_digest is None:
                # This should not happen, as the inventory should always include
                # a manifest file
                raise FoliantInventoryGenerationError(f"Inventory for version {version_dir} is missing.")

            version_digests[version] = version_digest

        # Check digests of existing versions against those of the root inventory
        for version, version_digest in version_digests.items():
            if version_digest in root_inventory.digests:
                # This version has already had its inventory added to the root
                # inventory, so there is no need to check it again
                continue

            if version_digest not in self.digests:
                self.digests.append(version_digest)

        # Check if each stream digest is already present in a previous version
        for version, inventory in stream_inventories.items():
            for stream, stream_digests in inventory.streams.items():
                for stream_digest in stream_digests:
                    if stream_digest in version_digests.values():
                        continue

                    if stream_digest in self.digests:
                        # This stream digest has already been added to a
                        # previous version, so there is no need to check it again
                        continue

                    self.digests.append(stream_digest)

        # Check if each file digest is already present in a previous version
        for version, inventory in version_inventories.items():
            for path, digest in inventory.files.items():
                if digest in self.digests:
                    # This file digest has already been added to a
                    # previous version, so there is no need to check it again
                    continue

                self.digests.append(digest)

        # Clear any duplicate digests
        self.digests = list(dict.fromkeys(self.digests))

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_version = version_dirs[0]

    # Validate that each version has an inventory by checking that there is a
    # version_init.edn or version_init.json file present
    for version in version_dirs:
        if version == root_version:
            continue
        version_path = os.path.join(self.path, version)
        inventory_path = os.path.join(version_path, "inventory", "version_init.edn")
        if not os.path.isfile(inventory_path):
            raise ValueError(f"Version {version_path} does not have an inventory!")

    # Build a list of all content items not in the root inventory
    root_inventory_digests = set([])
    for version in version_dirs:
        if version == root_version:
            continue
        root_inventory_digests |= self.get_inventory(version)

    # For each version, generate the inventory diff and check that the digests
    # are all the same as in the root inventory
    for version in version_dirs:
        if version == root_version:
            continue
        inventory_diff = self.get_inventory_diff(version, root_version)
        for digest in inventory_diff:
            if digest in root_inventory_digests:
                root_inventory_digests.remove(digest)
            else:
                raise ValueError(f"Digest {digest} is in version {version} but not in the root inventory!")

    # Check that there are no more digests in the root inventory that exist in
    # any other version
    if root_inventory_digests:
        raise ValueError(f"There are {len(root_inventory_digests)} digests in the root inventory that are not in any other version!")

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """

    if not os.path.exists(path):
        return "Path not found: {}".format(path)

    if not os.path.isdir(path):
        return "Path is not a directory: {}".format(path)

    root_namaste_file = os.path.join(path, "0=*.trc")
    if not os.path.exists(root_namaste_file):
        return "Could not find a '0=*.trc' file in the root directory"

    try:
        with open(root_namaste_file, "r") as f:
            if "ocfl_object" in f.read():
                return "object"
            else:
                return "root"
    except Exception as e:
        return "Error reading '0=*.trc' file: {}".format(e)

    return "Could not determine type of thing at path: {}".format(path)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        with open(os.path.join(path, "0=*"), "r") as f:
            # Assuming this is a Namaste file, look at the Root/Prefix/Inventory record
            # to determine the type of directory.
            first_line = f.readline().strip()
            if first_line.startswith("Root:"):
                return "root"
            elif first_line.startswith("Prefix:"):
                return "object"
            elif first_line.startswith("Inventory:"):
                if path.endswith(".file"):
                    return "file"
                else:
                    return "root"
            else:
                return "unknown"
    except FileNotFoundError:
        return "unknown"

