def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params

        Arguments:
            params (dict): The Bugzilla parameters
            bug_ids (list): A list of bug IDs

        This method amends the Bugzilla parameters with the specified bug IDs.
        """
        if not params:
            raise ValueError("Params must not be empty")
        if not bug_ids:
            raise ValueError("Bug IDs must not be empty")

        for param in params:
            if param == "Bugzilla_ids":
                # Update the list of Bugzilla IDs
                params[param] = bug_ids
                break
        else:
            # Add the Bugzilla IDs parameter
            params.append({"name": "Bugzilla_ids", "value": bug_ids})

        return params

def amend_bzparams(self, params, bug_ids):
    for bug_id in bug_ids:
        # check if the bug ID is already present in the params
        if bug_id in params:
            # if it is, then add it to the list of bug IDs for that param
            bug_ids = params[bug_id]
            bug_ids.append(bug_id)
        else:
            # if it's not, then add a new entry for the param with the bug ID as its value
            params[bug_id] = [bug_id]
    return params

