                    child_map = existing_mapping[child_key.value]
                    if not isinstance(child_map, ruamel.yaml.nodes.MappingNode):
                        child_map = ruamel.yaml.comments.CommentedMap()
                        existing_mapping[child_key.value] = child_map
                else:
                    child_map = ruamel.yaml.comments.CommentedMap()
                    existing_mapping[child_key.value] = child_map

                # add the new value or scalar
                if isinstance(node[1], ruamel.yaml.nodes.MappingNode):
                    for sub_key in node[1].value[child_key]:
                        if isinstance(sub_key, ruamel.yaml.nodes.ScalarNode) and isinstance(sub_key.value, str):
                            existing_value = child_map[sub_key.value]
                            if not isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                                child_map[sub_key.value] = sub_key.value
                        else:
                            child_map[sub_key.value] = sub_key.value
                else:
                    existing_value = child_map[child_key.value]
                    if not isinstance(existing_value, ruamel.yaml.nodes.MappingNode):
                        child_map[child_key.value] = child_key.value
        else:
