def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """

    parsed_args = {}
    remaining_args = []

    for arg in unparsed_arguments:
        if arg.startswith('-'):
            # this is an argument to be claimed by a subparser
            for name, subparser in subparsers.items():
                # see if this subparser will accept this argument
                if subparser.parse_known_args([arg])[1]:
                    # this subparser will accept this argument, so claim it
                    try:
                        parsed_args[name] = subparser.parse_args([arg])
                    except SystemExit:
                        # the subparser raised a SystemExit exception, indicating that it
                        # does not want to accept this argument. skip it and move on to the next
                        pass
                    break
            else:
                # no subparser claimed this argument, so it must be a bad argument
                raise ValueError('unrecognized argument: ' + arg)
        else:
            # this is a non-argument, so it must be a command to be handled by a subparser
            for name, subparser in subparsers.items():
                # see if this subparser will accept this command
                if subparser.parse_known_args([arg])[1]:
                    # this subparser will accept this command, so perform the requested action
                    parsed_args[name] = subparser.parse_args([arg])
                    break
            else:
                # no subparser claimed this command, so it must be a bad command
                raise ValueError('unrecognized command: ' + arg)

    # extract all remaining arguments that were not claimed by any subparser
    for arg in unparsed_arguments:
        if arg.startswith('-'):
            continue
        remaining_args.append(arg)

    return parsed_args, remaining_args

