def size_to_bytes(size: str) -> int:
    size_unit_map = {"K": 1000, "M": 1000000, "G": 1000000000}
    size_with_unit = size.upper()
    if not size_with_unit.endswith(tuple(size_unit_map.keys())):
        raise ValueError(f"Invalid size unit: {size}")
    size_num = float(size[:-1])
    size_unit = size_with_unit[-1]
    return int(size_num * size_unit_map[size_unit])
