            print(f"Running command: {command}")
        p = subprocess.Popen(
            command,
            shell=True,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=(subprocess.PIPE if hide_stderr else None),
        )

        # get the output
