def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if cwd is not None and not isinstance(cwd, Path):
        cwd = Path(cwd)
    if not isinstance(args, list):
        args = [args]
    if env is not None and not isinstance(env, dict):
        env = dict(env)
    with subprocess.Popen(commands, cwd=cwd, env=env) as proc:
        if verbose:
            print(proc.args)
        if hide_stderr:
            stderr = None
        else:
            stderr = subprocess.STDOUT
        try:
            proc.communicate(args, stdout=subprocess.PIPE, stderr=stderr)
        except ArgumentsError as e:
            raise CommandError(f"Invalid arguments provided for command: {commands}\n{e.args}")
        if proc.returncode != 0:
            raise CommandError(f"Command returned non-zero exit status: {proc.returncode}\nOutput: {proc.communicate()[0].decode().strip()}")
    return True
