            raise ValueError("hist must be a histogram")

        if make_value is not None and not callable(make_value):
            raise ValueError("make_value must be a function or None")

        if get_coordinate not in ["left", "right", "middle"]:
            raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

        if not isinstance(field_names, tuple):
            raise ValueError("field_names must be a tuple")

        if not len(field_names) == 2:
            raise ValueError("field_names must have length 2")

        if scale is not None and not isinstance(scale, Scale):
            raise ValueError("scale must be a scale or None")

        #convert histogram to graph
        graph = Graph(scale=scale)

        for i, bin in enumerate(hist):
            if make_value is None:
                value = bin.content
            else:
                value = make_value(bin.content)

            if get_coordinate == "left":
                x = bin.left - bin.width / 2
            elif get_coordinate == "right":
                x = bin.right - bin.width / 2
            else:
                x = bin.left

            graph.add_point((x, value), field_names=field_names)

        return graph

