def _verify(iface, candidate, tentative=False, vtype=None):
    # Make sure the candidate claims that it provides the interface
    iface.providedBy(candidate, vtype)

    # Making sure the candidate defines all the necessary methods
    candidate_methods = {name for name in dir(candidate)
                          if callable(getattr(candidate, name))}
    iface_methods = {name for name in dir(iface)
                     if callable(getattr(iface, name))}
    for name in iface_methods:
        if name not in candidate_methods:
            raise Invalid("Method not defined: '{}'".format(name))

    # Making sure the methods have the correct signature (to the extent possible)
    for name in iface_methods:
        iface_sig = signature(getattr(iface, name))
        candidate_sig = signature(getattr(candidate, name))
        if iface_sig != candidate_sig:
            raise Invalid("Method signature does not match: '{}'. Expected {} and got {}".format(name, iface_sig, candidate_sig))

    # Making sure the candidate defines all the necessary attributes
    candidate_attrs = {name for name in dir(candidate)
                        if not callable(getattr(candidate, name))}
    iface_attrs = {name for name in dir(iface)
                   if not callable(getattr(iface, name))}
    for name in iface_attrs:
        if name not in candidate_attrs:
            raise Invalid("Attribute not defined: '{}'".format(name))

