def verifyObject(iface, candidate, tentative=False):
    """Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the interface using ``iface.providedBy`` (unless *tentative* is `True`, in which case this step is skipped)
    - Making sure the candidate defines all the necessary methods
    - Making sure the methods have the correct signature (to the extent possible)
    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be checked passed
    :raises zope.interface.Invalid: If any of the previous conditions do not hold

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors are collected and reported. Previously, only the first error was reported. As a special case, if only one such error is present, it is raised alone, like before.
    """
    if not tentative:
        # Verify that the candidate claims that it provides the interface
        iface.providedBy(candidate)

    # Verify that the candidate defines all the necessary methods
    for method in iface.__provides__:
        if not hasattr(candidate, method):
            raise zope.interface.Invalid("Candidate does not define the method %s" % method)

    # Verify that the candidate defines all the necessary attributes
    for attribute in iface.__attributes__:
        if not hasattr(candidate, attribute):
            raise zope.interface.Invalid("Candidate does not define the attribute %s" % attribute)

    # Verify that the methods have the correct signature (to the extent possible)
    for method in iface.__provides__:
        candidate_method = getattr(candidate, method)
        for signature in iface.methodSignatures(method):
            try:
                inspect.signature(candidate_method)
            except (ValueError, TypeError):
                raise zope.interface.Invalid("Method %s has an invalid signature" % method)

    return True

