class ISOParser:
    @_takes_ascii
    def isoparse(self, dt_str):
        """Parse an ISO-8601 datetime string into a datetime.datetime.

        Arguments:
            dt_str: A string or stream containing only an ISO-8601 datetime string

        Returns:
            datetime.datetime representing the string. Unspecified components default to their lowest value.
        """

        self.dt_str = dt_str

        # Initialize values for all parts of the datetime string
        self.year = None
        self.month = None
        self.day = None
        self.hour = None
        self.minute = None
        self.second = None
        self.microsecond = None
        self.tzinfo = None
        self.timezone_offset = None

        # Parse the datetime string
        self._parse_date()
        self._parse_time()
        self._parse_timezone()

        if self.year is None:
            raise ISOParseError("Year not provided")

        if self.month is None:
            raise ISOParseError("Month not provided")

        if self.day is None:
            raise ISOParseError("Day not provided")

        datetime_root_info = {
            "year": self.year,
            "month": self.month,
            "day": self.day,
            "hour": self.hour,
            "minute": self.minute,
            "second": self.second,
            "microsecond": self.microsecond,
            "tzinfo": self.tzinfo,
        }

        # Use the Python datetime constructor to create the datetime object
        return datetime(**datetime_root_info)

    def _parse_date(self):
        """Parse the date part of the ISO8601 datetime string."""

        date_match = re.search(r"([0-9]{4})-([0-9]{2})-([0-9]{2})", self.dt_str)

        if date_match:
            self.year = int(date_match.group(1))
            self.month = int(date_match.group(2))
            self.day = int(date_match.group(3))

        else:
            date_match_alternate = re.search(
                r"([0-9]{4})([0-9]{2})([0-9]{2})", self.dt_str
            )

            if date_match_alternate:
                self.year = int(date_match_alternate.group(1))
                self.month = int(date_match.group(2))
                self.day = int(date_match.group(3))

    def _parse_time(self):
        """Parse the time part of the ISO8601 datetime string."""

        time_match = re.search(
            r"T([0-9]{2}):([0-9]{2}):([0-9]{2})(\.([0-9]{1,6}))?", self.dt_str
        )

        if time_match:
            self.hour = int(time_match.group(1))
            self.minute = int(time_match.group(2))
            self.second = int(time_match.group(3))

            if time_match.group(5):
                self.microsecond = int(time_match.group(5)) * 10 ** (6 - len(time_match.group(5)))

    def _parse_timezone(self):
        """Parse the time zone offset part of the ISO8601 datetime string."""

        tz_match = re.search(r"([+-]([0-9]{2}):([0-9]{2})|Z)", self.dt_str)

        if tz_match:
            if tz_match.group(1) == "Z":
                self.tzinfo = datetime.timezone.utc

            else:
                hour_offset = int(tz_match.group(2))
                minute_offset = int(tz_match.group(3))

                if hour_offset < 0:
                    hour_offset *= -1

                if minute_offset < 0:
                    minute_offset *= -1

                self.tzinfo = datetime.timezone(datetime.timedelta(
                    hours=hour_offset, minutes=minute_offset))

