def _takes_ascii(f):
    @wraps(f)
    def wrapper(dt_str, **kwargs):
        if not isinstance(dt_str, str):
            raise TypeError("dt_str should be an ASCII string")
        return f(dt_str, **kwargs)
    return wrapper

