def find_tags(text,replacer=None):
    """
    Finds tags in text.

    Ignores tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    replaced_text = ""
    inside_code = False

    for i in range(len(text)):
        char = text[i]

        if char == '`':
            inside_code = not inside_code

        if not inside_code:
            if char == '#':
                if text[i+1:i+2] == '#':
                    if replacer:
                        replaced_text += text[i:i+2]
                        i += 1
                    else:
                        tags.add(text[i+1:i+2])

    if replaced_text:
        return tags, replaced_text
    else:
        return tags, text

