def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.

    Parameters:
        public_key (str): The public key of the author
        doc (:class: `Document`): A document
        signature (dict): The signature of the message
    """
    if not isinstance(public_key, str):
        raise ValueError("The public key must be a string")
    if not isinstance(doc, Document):
        raise ValueError("The document must be a valid Document instance")
    if not isinstance(signature, dict):
        raise ValueError("The signature must be a dictionary")

    signed_elements = []
    for element in doc.elements:
        if element.type == "annotation" and element.attribs["role"] == "header":
            signed_elements.append(element)

    if len(signed_elements) == 0:
        raise ValueError("There are no signed elements in the document")

    signed_string = ""
    for element in signed_elements:
        signed_string += element.text

    verify = cryptography.signature.verify(signed_string, public_key, signature)

    if not verify:
        raise ValueError("The signature is invalid")

    return True

