import os

class IniType(ComplexType):
    """
    The IniType class represents a complex type that is used to represent the ``ini_type`` attribute of an ``ini_section`` in the Foliant project settings.
    """

    value = Field(str, required=True)

    def __init__(self, value):
        self.value = value

    @classmethod
    def from_ini_section(cls, section):
        """
        Create a new IniType object from the given INI section.

        Args:
            section: The INI section to create the object from.

        Returns:
            The created IniType object.
        """
        if not section.get('name') == 'ini_type':
            raise ValueError("The given INI section is not an 'ini_type' section.")
        if len(section.items()) > 1:
            raise ValueError("The given INI section has multiple items.")
        for item_name, item_value in section.items():
            return IniType(item_value)

    def to_ini_section(self):
        """
        Convert the IniType object to an INI section.

        Returns:
            The created INI section.
        """
        return {'name': 'ini_type', 'items': [self.value], }

