    """Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file
    :raise IRValidatorException: When mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    if not spec_content:
        raise IRValidatorException("Missing spec content")

    spec_data = load_yaml(spec_content)

    if not spec_data.get("id"):
        raise IRValidatorException("Missing ID field in spec")

    if not spec_data.get("version"):
        raise IRValidatorException("Missing version field in spec")

    if not spec_data.get("entry_point"):
        raise IRValidatorException("Missing entry point field in spec")

