def validate_from_content(cls, spec_content):
    """
    Validates that the specified YAML content contains all required fields.

    :param spec_content: the YAML content of the spec file
    :type spec_content: str
    :raises IRValidatorException: when mandatory data is missing in the spec file
    :return: a dictionary with the loaded data from the spec file
    :rtype: dict
    """
    yaml = YAML()

    try:
        spec = yaml.load(spec_content)
    except ParserError:
        raise IRValidatorException("Invalid YAML content.")

    invalid_keys = set(spec.keys()) - cls.REQUIRED_KEYS
    if invalid_keys:
        raise IRValidatorException(
            "The following mandatory keys are missing in the spec file: "
            f"{', '.join(invalid_keys)}.")

    missing_values = {
        key: value for key, value in cls.REQUIRED_FIELD_VALUES.items()
        if spec.get(key) != value
    }
    if missing_values:
        raise IRValidatorException(
            "The following mandatory key-value pairs are missing in the spec file: "
            f"{', '.join(f'{key}: {value}' for key, value in missing_values.items())}.")

    invalid_values = {
        key: value for key, value in spec.items()
        if (value is not None and key in cls.REQUIRED_FIELD_VALUES
            and cls.REQUIRED_FIELD_VALUES[key] != value)
    }
    if invalid_values:
        raise IRValidatorException(
            "The following key-value pairs have invalid values in the spec file: "
            f"{', '.join(f'{key}: {value}' for key, value in invalid_values.items())}.")

    missing_fields = {
        field for field in cls.REQUIRED_FIELDS
        if field not in spec.get("fields", [])
    }
    if missing_fields:
        raise IRValidatorException(
            "The following mandatory fields are missing in the spec file: "
            f"{', '.join(missing_fields)}.")

    return spec

def validate_from_content(cls, spec_content):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    valid_content = {}
    # check if the required fields are all present
    for required_field in cls.REQUIRED_FIELDS:
        if required_field not in spec_content:
            raise IRValidatorException(f"Required field {required_field} is missing from the spec file")
    # check if the field values are valid
    for field, field_value in spec_content.items():
        if field in cls.VALID_FIELD_MAP:
            field_type = cls.VALID_FIELD_MAP[field]
            if field_value is not None and not isinstance(field_value, field_type):
                raise IRValidatorException(f"Value for field {field} is not a valid {field_type}")
        elif field not in cls.IGNORED_FIELDS:
            raise IRValidatorException(f"Invalid field {field} in the spec file")
    # check if the field ranges are valid
    for field, range_values in cls.RANGE_FIELD_MAP.items():
        if field not in spec_content:
            continue
        value = spec_content[field]
        if not isinstance(value, range_values["type"]):
            raise IRValidatorException(f"Value for field {field} is not a {range_values['type']}")
        if range_values["min"] is not None and value < range_values["min"]:
            raise IRValidatorException(f"Value for field {field} is lower than the minimum allowed value ({range_values['min']})")
        if range_values["max"] is not None and value > range_values["max"]:
            raise IRValidatorException(f"Value for field {field} is higher than the maximum allowed value ({range_values['max']})")
    # check if the field values are valid
    for field, value in spec_content.items():
        if field not in cls.VALID_FIELD_MAP:
            continue
        if value is None or not cls.VALID_FIELD_MAP[field](value):
            raise IRValidatorException(f"Value for field {field} is not valid")
    # everything seems to be OK
    valid_content.update(spec_content)

