    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("_control_"):
            control_args[arg[len("_control_"):]] = True
        elif arg.startswith("_nested_"):
            nested_args[arg[len("_nested_"):]] = True
        elif arg.startswith("_custom_"):
            custom_args[arg[len("_custom_"):]] = True

    return control_args, nested_args, custom_args

def get_nested_custom_and_control_args(self, args):
    """ Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """

    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if isinstance(arg, str) or isinstance(arg, bool):
            # Keyword arguments requiring no nested structure
            if arg.startswith("--no-"):
                key = arg.replace("--no-", "")
                if key not in control_args:
                    control_args[key] = False
            else:
                key = arg.lstrip("--")
                if key not in control_args:
                    control_args[key] = True
        elif isinstance(arg, dict):
            # Addition keyword arguments with nested structure
            for key, value in arg.items():
                if key.startswith("--no-"):
                    key = key.replace("--no-", "")
                    if key not in control_args:
                        control_args[key] = value
                else:
                    key = key.lstrip("--")
                    if key not in control_args:
                        if key in nested_args:
                            raise ValueError("Duplicate argument '{}'".format(key))
                        else:
                            nested_args[key] = value
        else:
            # Custom variable being used instead of normal nested usage
            key = str(arg)
            if key.startswith("ansible_var_"):
                key = key[len("ansible_var_"):]
            custom_args[key] = arg

    return control_args, nested_args, custom_args

