            values_dict[arg] = self.argument_transform_map[parser_name][arg](arg_value)

    # Remove all invalid or unnecessary arguments
    keep_args = set()
    for arg, arg_type in self.argument_type_map[parser_name].items():
        if arg not in values_dict:
            continue
        if isinstance(arg_type, type):
            # Value was provided explicitly, so it's valid
            keep_args.add(arg)
        elif arg_type == "nargs" or arg_type == "const":
            # Value can be None, so keep the arg
            keep_args.add(arg)

    spec_args = set(self.argument_type_map[parser_name].keys())
    invalid_args = keep_args & spec_args - set(values_dict.keys())
    for arg in invalid_args:
        del values_dict[arg]

        return

